    /** A workbench: the one named (its name or its address), else the selected one, else the first. */
    public static Bench open(Door client, String name, boolean raiseRefusals) {
        Map<String, Object> state = map(client.call("get_state", null));
        List<Map<String, Object>> every = new ArrayList<>();
        // A laboratory's workbenches, then a REAL account's (paper among them).
        for (String area : new String[] {"laboratories", "accounts"}) {
            for (Object home : list(state.get(area))) {
                for (Object b : list(map(home).get("benches"))) {
                    every.add(map(b));
                }
            }
        }
        if (name != null) {
            List<String> names = new ArrayList<>();
            for (Map<String, Object> b : every) {
                if (name.equals(b.get("uri")) || name.equals(b.get("name"))) {
                    return new Bench(client, (String) b.get("uri"), (String) b.get("name"), raiseRefusals);
                }
                names.add("'" + b.get("name") + "'");
            }
            throw new Client.McpException("no workbench is named '" + name + "'; there are " + (names.isEmpty() ? "none" : String.join(", ", names)));
        }
        if (every.isEmpty()) {
            throw new Client.McpException("the workspace holds no laboratory workbench");
        }
        Object selected = state.get("selected");
        for (Map<String, Object> b : every) {
            if (selected != null && selected.equals(b.get("uri"))) {
                return new Bench(client, (String) b.get("uri"), (String) b.get("name"), raiseRefusals);
            }
        }
        return new Bench(client, (String) every.get(0).get("uri"), (String) every.get(0).get("name"), raiseRefusals);
    }

