    private List<Object> stream(String tail) {
        List<Object> all = new ArrayList<>();
        String after = null;
        while (true) {
            Map<String, Object> page = map(read(tail, after));
            List<Object> items = list(page.get("items"));
            if (items.isEmpty()) {
                return all;
            }
            all.addAll(items);
            Object next = page.get("next");
            if (!(next instanceof String s)) {
                return all;
            }
            after = s;
        }
    }

    /**
     * To the next close: a workbench that has lived through no tick steps one first (a jump never invents a first
     * quote), then a candle of the interval; the closed candle is read back from the window.
     */
    private Map<String, Object> step(String interval, String symbol) {
        Object stood = map(readUri(uri)).get("cursor_ms");
        Map<String, Object> q = quoteOf(read("quotes", null), symbol);
        if (q == null || q.get("at_ms") == null) {
            c.call("replay_step", Map.of("bench", uri, "unit", "tick", "n", 1L));
        }
        Object now = map(c.call("replay_step", Map.of("bench", uri, "unit", "candle", "n", 1L, "timeframe", interval))).get("cursor_ms");
        if (now == null || now.equals(stood)) {
            return null;
        }
        Map<String, Object> got = map(c.call("bars_window", Map.of("bench", uri, "symbol", symbol, "frames", List.of(interval), "limit", 1L)));
        List<Object> rows = list(map(map(map(got.get("markets")).get(symbol)).get(interval)).get("rows"));
        if (rows.isEmpty()) {
            return null;
        }
        List<Object> r = list(rows.get(rows.size() - 1));
        Map<String, Object> candle = new LinkedHashMap<>();
        String[] names = {"time", "open", "high", "low", "close", "volume"};
        for (int i = 0; i < names.length; i++) {
            candle.put(names[i], r.get(i));
        }
        return candle;
    }

